    body: "NCEA(National Certificate of Educational Achievement)は、2002年に導入されたニュージーランドの中等教育修了資格であり、年間約15万人の生徒がこの資格取得を目指して学んでいる。ニュージーランド資格認証機構(NZQA)が制度を所管し、おおむね11〜13年生(高校2〜4年に相当)に対応するレベル1・2・3の3段階で構成される。各レベルの資格を取得するには合計80クレジット(単位)が必要であり、個々のスタンダード(学習内容のまとまり)ごとに獲得できるクレジットが定められている。\n\n評価方法には、年度末の全国統一試験による外部評価と、年間を通じて学校が行う課題やレポートなどによる内部評価があり、内部評価の採点結果はNZQAの独立したモデレーターによる点検を受けて全国的な評価基準との整合性が担保される。この柔軟な単位積み上げ方式により、生徒は学問的な科目と職業関連の科目を組み合わせて学ぶことができ、大学進学だけでなく職業訓練や就職への接続にも対応している。\n\nNCEAは長年、国内外で信頼性の高い資格として評価されてきたが、2025年8月にはニュージーランド政府がNCEAを廃止し、新たな中等教育修了資格制度に置き換える方針を発表しており、今後の制度転換の動向が比較教育学の観点からも注目されている。",
