    body: "アカデミーは、イングランドの公費維持学校の一類型で、非営利の信託(トラスト)が運営し、地方教育当局ではなく中央政府から直接資金を受ける。労働党政権下の2000年に「シティ・アカデミー」として、荒廃した都市部の不振校を立て直す目的で導入され、2002年には「シティ」の語が外されて都市部以外にも広がった。\n\n2010年のアカデミー法(Academies Act 2010)は、既存の公立学校が転換してアカデミーになる法的な仕組みを整え、拡大を大きく加速させた。親や団体が新設できる「フリー・スクール」も、アカデミーの一形態として位置づけられる。近年は複数校を束ねる「マルチ・アカデミー・トラスト(MAT)」による運営が大半を占めるようになった。\n\nアカデミーは、カリキュラムや教員の勤務条件、学期日程などで一定の自律性を持つ。支持者は革新と成績向上の機会を強調する一方、批判者は地方当局による調整機能の弱まり、トラストへの権限集中、説明責任や学校間格差の拡大を指摘しており、その効果をめぐる評価は一様ではない。",
