    body: "PISAの第1回調査(2000年実施)の結果、ドイツは読解力・数学的リテラシー・科学的リテラシーのいずれもOECD平均を下回り、社会経済的背景や移民的背景による成績差が大きいことも示された。それまで自国の教育に自信を持っていたドイツでは大きな衝撃と受け止められ、「PISAショック」と呼ばれた。OECDもこの経験を、国際調査が国内政策を動かした例として紹介している。\n\n対応として、各州と連邦は2000年代以降、全国共通の教育スタンダード(習得すべき能力の基準)の導入、学力の定期的な検証、終日学校(全日制学校)の拡充、就学前からの言語支援、移民の子どもへの支援などに取り組んだ。授業の「インプット」(教育内容)から「アウトプット」(身につけた力)への転換、コンピテンシー志向、外部評価の重視が政策の原則になったと整理される。\n\n同様に国際調査の結果が国内改革を促す現象は、日本の「PISAショック」(読解力の順位低下)など他国にも見られる。国際調査の数値が各国の政策を動かす力の大きさは、政策借用や国際的な標準化の議論とも結びついている。",
