    body: "フランスの公教育の世俗化は、1881〜82年のフェリー法による公立初等教育の無償・義務・世俗化にさかのぼる。1905年の政教分離法で国家と教会の分離が確立し、さらに1946年憲法前文で公教育のライシテが憲法的な価値と位置づけられた。公立学校は、特定の宗教教育を行わず、あらゆる信条の子どもを平等に受け入れる共和国の場とされる。\n\n1989年にムスリムの女子生徒がスカーフを着けて公立中学校に登校して問題となった事件を契機に、学校でのライシテの解釈が全国的な論争となった。2004年3月には、公立学校で宗教的帰属を明示する標章や服装の着用を禁止する法律が成立し、同年9月に施行された。政府は宗教差別が目的ではないと説明したが、イスラム教徒を標的にしているとの強い批判も起きた。\n\nライシテは、信教の自由と共和国の価値の共有、あるいは多文化社会における統合のあり方をめぐる議論と深く関わる。日本の政教分離や宗教教育のあり方、多文化共生教育を比較して考える際にも重要な参照事例である。",
