    body: "国家教育政策2020(National Education Policy 2020)は、2020年7月29日にインド連邦内閣が承認した政策文書で、1986年の政策に代わるものである。学校教育を3歳から18歳まで「5+3+3+4」の4段階(基礎段階、準備段階、中間段階、中等段階)に再編し、これまでの10+2の区分を改める構想を示した。\n\n言語面では、少なくとも5年生まで、可能なら8年生以降も、家庭の言語・母語・地域言語を教授言語とすることが望ましいとした。また三言語方式を掲げ、児童生徒が三つの言語を学び、そのうち少なくとも二つはインド固有の言語とするとしている。どの言語も強制しないと明記され、実施は州や学校に委ねられると説明されたが、タミル・ナードゥ州など一部の州は言語政策への反対を表明し、連邦と州の関係をめぐる政治的議論となった。\n\nインドでは、2009年に成立した無償義務教育に関する子どもの権利法(RTE法)など、アクセス拡大の取り組みが先行してきた。NEP2020は、アクセスから学習の質と柔軟なカリキュラムへの重心の移行を示す政策として、比較教育学の注目を集めている。",
