    body: "「教員の地位に関する勧告」は、1966年10月5日にパリで、ユネスコがILO(国際労働機関)と協力して開催した特別政府間会議で採択された。教員の権利と責任、養成、採用、昇進、雇用・労働条件、教育への参加と協議・交渉などについて、各国政府が従うべき基準を示している。\n\n勧告は条約と異なり法的拘束力を持たないが、教職を専門職として位置づけ、その地位と待遇を国際的に規範化した点で影響が大きい。教員が教育上の意思決定に協議や交渉を通じて参加できること、専門職としての自由が尊重されることなどが重視される。\n\n勧告の履行状況は、1967年に設置されたILO・ユネスコ合同専門家委員会(CEART)が監視しており、3年ごとに各国の適用状況を審査して報告する。CEARTの対象には、のちに1997年の高等教育教員の地位に関するユネスコ勧告も加わった。教員の多忙化や待遇改善をめぐる各国の議論の基準点として、現在もしばしば参照される。",
