    slug: "isced",
    title: "ISCED(国際標準教育分類)",
    reading: "あいせっど",
    kana: "A–Z",
    categories: ["comparative"],
    summary:
      "各国で異なる教育制度を国際比較できるよう、ユネスコが定めた教育段階の分類基準。2011年版では教育レベルを0から8の9段階に区分する。",
    body: "ISCED(International Standard Classification of Education)は、各国の教育プログラムとそれに基づく資格を共通の枠組みで分類するための国際基準で、ユネスコ統計研究所(UIS)が策定・維持している。1970年代半ばに開発され、1997年に改訂され、2011年11月のユネスコ総会で現行のISCED 2011が採択された。\n\nISCED 2011は教育レベルを0から8の9段階に分ける。レベル0は幼児教育、1は初等教育、2は前期中等教育、3は後期中等教育、4は高等学校卒業後の非高等教育、5は短期高等教育、6は学士課程またはそれに相当する課程、7は修士課程またはそれに相当する課程、8は博士課程またはそれに相当する課程である。1997年版に比べ、幼児教育の拡大と高等教育の構造の変化を反映して改められた。教育分野の分類(ISCED-F 2013)は、これと対になる分類である。\n\nOECDの『図表でみる教育(Education at a Glance)』など、多くの国際統計や調査がISCEDに基づく。たとえば日本の高校は後期中等教育(レベル3)に当たるといったように、制度の異なる国々の就学率、教育支出、学歴別の統計を比較可能にする基盤となる。",
