    body: "DeSeCo(Definition and Selection of Competencies)は、OECDが国際的・学際的に実施したプロジェクトで、その成果は2003年に『Key Competencies for a Successful Life and a Well-Functioning Society』として公刊された。PISAなどの国際調査が測る能力の理論的な根拠を与える目的を持つ。\n\nキー・コンピテンシーは3つのカテゴリーに整理される。(1)道具を相互作用的に用いる(言語、知識、情報技術などの道具を目的に合わせて活用する)、(2)異質な集団で交流する(他者と良好な関係を築き、協働し、対立を管理・解決する)、(3)自律的に行動する(自分の人生を管理し、社会の広い文脈の中に位置づけ、自分の判断で行動する)である。その中心には、省察的に考え行動する力が置かれた。\n\nこの枠組みは、知識の量よりも活用する力を重視する流れを方向づけ、各国のカリキュラム改革に影響を与えた。日本の学習指導要領が掲げる資質・能力の議論とも関連する。その後OECDは、「ラーニング・コンパス2030」へと発展させている。",
