    body: "マルク=アントワーヌ・ジュリアン(通称ジュリアン・ド・パリ、1775〜1848)は、フランスの人物で、1817年にパリで『比較教育に関する著作の構想と予備的見解』(Esquisse et vues préliminaires d'un ouvrage sur l'éducation comparée)を出版した。この文書は、比較教育学の先駆けとして広く言及される。\n\nジュリアンは、教育を事実の収集と整理に基づく「実証的な科学」にしようとした。具体的には、まずスイスの22州やドイツの一部の教育を調査し、のちにヨーロッパ全体に広げる計画を立て、各国の教育制度の情報を共通の様式で集めるための「比較観察表」のひな形を示した。調査の方法を標準化する発想は、後世の国際的な教育統計や国際調査の原型ともいえる。\n\nただし、彼を「創始者」とする見方は後年の再評価によるもので、この提案が直ちに学問分野を形づくったわけではないとする批判的な見解もある。19世紀の国別研究から、サドラーやベレディなどによる方法論的な議論へと比較教育学が展開する歴史の起点として位置づけられる。",
