    body: "スウェーデンにおける包括学校（グルンドスコーラ）は、1962年の教育改革によって導入された義務教育制度の中核である。第二次世界大戦後の民主化と社会福祉国家の建設を背景に、従来の早期分岐型学校体系を廃止し、すべての国民に平等な教育機会を保障することを目的として創設された。\n\n制度としては7歳から16歳までの9年間を単一の学校で過ごす単線型体系をとる。前期中等段階に至るまで学力による選抜やコース分けを行わず、共通カリキュラムのもとで個別指導を重視する。1990年代以降は地方自治体への権限委譲や独立学校（フリスクーラ）の参入による学校選択制が導入され、学校運営の多様化と競争原理が進展した。\n\n日本における義務教育学校や小中一貫教育の推進において、子どもの発達段階に応じた柔軟な指導体制や、早期選抜を避けて後期中等教育への接続を図るスウェーデンの実践は重要な示唆を与えている。また、選択制導入に伴う教育格差の拡大など、現代的課題への対応策も示唆に富む。",
