    body: "カナダの教育制度における最大の特徴は、連邦政府に教育省が存在せず、各州および準州が教育に関する主権的権限を専管する点にある。1867年憲法法（英領北アメリカ法）第93条に基づき、教育の管轄権が各州に明記されており、地域ごとの文化的・言語的・宗教的独自性を尊重した統治構造が確立された。\n\n各州の教育省がカリキュラムの編成、教員免許の授与、学校予算の配分、卒業要件の策定を独自に行う。国レベルの調整機関としては、各州教育大臣で構成される州教育大臣会議（CMEC）が存在し、全州規模の政策協調や国際的な教育調査への対応を協議する。公立カトリック校の設置など州ごとの歴史的経緯に応じた柔軟な制度設計が認められている。\n\n中央集権的な指導要領と地方教育委員会の関係を見直す日本の教育行政改革において、カナダの州主権モデルは、地方の自律的な教育政策展開と全国的な教育の質保証をいかに両立させるかという点に関して貴重な示唆を与えている。",
