    body: "OECD国際指導環境調査（TALIS）の分析枠組みとは、各国の教員の指導環境、学校の学習環境、教員の職能開発の実態を教員および校長に対する質問紙調査によって定量的・定性的に把握し、国際比較を可能とする調査体系である。2008年より5年ごとに実施されている。\n\n調査では、教員の勤務時間と業務内容の内訳、指導に対する自己効力感、同僚との協働体制、授業方法、校長のリーダーシップなどを多角的に測定する。得られたデータは多変量解析によって分析され、効果的な教育条件や教員支援の要因が国際比較を通じて特定される。\n\n日本の教員の勤務時間が際立って長いことや、授業外業務の過重、自己効力感の課題を客観的データとして明確に示した。学校における働き方改革の推進や、チーム学校の構築、教員の専門性向上に向けた政策立案において、最も不可欠な国際的根拠となっている。",
